pts_set=set(pts)
# output pattern
out_pts={(4,6),(5,5),(5,6),(5,7),(6,5),(6,7)}
def canon(s):
    mr=min(r for r,c in s); mc=min(c for r,c in s)
    return frozenset((r-mr,c-mc) for r,c in s)
def transforms(s,h,w):
    # apply dihedral on shape coords in local bbox
    a=canon(s); hh=max(r for r,c in a)+1; ww=max(c for r,c in a)+1
    trans=[]
    for refl in (False,True):
      for k in range(4):
        x=set()
        for r,c in a:
          if refl: c=ww-1-c
          # rotate cw square? non-square use coords normalized each time
          x.add((r,c))
        hh2=max(r for r,c in x)+1; ww2=max(c for r,c in x)+1
        for _ in range(k):
          x={(c,hh2-1-r) for r,c in x}; hh2,ww2=ww2,hh2
        trans.append(canon(x))
    return set(trans)
Ocanon=canon(out_pts)
