def mat_from_shape(s):
 h=max(r for r,c in s)+1; w=max(c for r,c in s)+1
 return [''.join('#' if (r,c) in s else '.' for c in range(w)) for r in range(h)]
def rot_cw(s):
 h=max(r for r,c in s)+1; w=max(c for r,c in s)+1
 return {(c,h-1-r) for r,c in s}
def rot_ccw(s):
 h=max(r for r,c in s)+1; w=max(c for r,c in s)+1
 return {(w-1-c,r) for r,c in s}
def refl_h(s):
 h=max(r for r,c in s)+1; w=max(c for r,c in s)+1
 return {(r,w-1-c) for r,c in s}
for label, s in [('D1src',{(0,0),(0,1),(0,2),(1,1)}),('D1out',{(0,0),(1,0),(1,1),(2,0)}),('D3src',canon({(6,6),(6,7),(7,5),(7,6),(8,6),(8,7)})),('D3out',canon(out_pts))]:
 print('\n',label,mat_from_shape(s))
 for name,f in [('cw',rot_cw),('ccw',rot_ccw),('180',lambda a: rot_cw(rot_cw(a))),('fh',refl_h)]:
  print(name,mat_from_shape(canon(f(s))))

